                        <button
                          type="button"
                          onClick={() => removeOption(cls.id, opt)}
                          className="rounded-full hover:bg-[var(--primary)]/20"
                          aria-label={`Xóa ${opt}`}
                        >
                          <X className="size-3" />
                        </button>
